//! Parity with Brickpress 1.x. The fixtures were generated by the TypeScript
//! implementation (src/lib) before it was retired.

use brickpress_core::persistence::document::{create_document, parse_document, serialize_document};
use brickpress_core::spatial::can_place;
use brickpress_core::PlacedPiece;
use serde::Deserialize;
use std::collections::HashSet;
use std::sync::Arc;

#[derive(Deserialize)]
struct Case {
    a: PlacedPiece,
    b: PlacedPiece,
    fits: bool,
}

#[test]
fn collision_matches_1x_for_4000_random_pose_pairs() {
    let cases: Vec<Case> = serde_json::from_str(include_str!("fixtures/collision-parity.json")).unwrap();
    let mut mismatches = Vec::new();
    for (i, case) in cases.iter().enumerate() {
        let mut doc = create_document(false);
        doc.board = brickpress_core::Board { width: 12, height: 12 };
        doc.passes[0].pieces = Arc::new(vec![case.a.clone()]);
        if can_place(&doc, std::slice::from_ref(&case.b), &HashSet::new()) != case.fits {
            mismatches.push(i);
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches, first: {:?}",
        mismatches.len(),
        &mismatches[..mismatches.len().min(10)]
    );
}

#[test]
fn starter_document_matches_1x_exactly() {
    let text = include_str!("fixtures/starter-1x.json");
    let theirs = parse_document(text).unwrap();
    assert_eq!(theirs, create_document(true));
    // Same JSON text, apart from line endings.
    assert_eq!(serialize_document(&create_document(true)), text.replace("\r\n", "\n"));
}
